import json, sys, os
D = os.path.dirname(os.path.abspath(__file__))
PREFIX = "Flat vector cartoon sticker art for a cute 2D side-scrolling mobile game: thick uniform dark-purple outlines (#2b2233) around every shape, flat color fills with exactly one hard-edged cel-shade step, no gradients, no texture, warm sunset palette of coral, peach, cream, lavender and teal accents, clean bold graphic shapes readable at small size, strict side view orthographic elevation, transparent background, absolutely no text, no letters, no numbers, no digits, no logos, no brand trade dress."
CHIBI = "chibi proportions about 2.5 heads tall: big head, short body and short limbs (same proportions as the reference protagonist)"
HERO = "0f150346-517d-4023-8805-68e447b7731e"

JOBS = {
 "heads": dict(ar="16:9", ref=[HERO], p=PREFIX + " Character: the same protagonist as the reference image, " + CHIBI + ". This image is an expression sheet showing ONLY his HEAD, three times. Identity must match the reference exactly: black messy spiky hair with a lavender highlight streak, peach skin, round peach ear, simple dot-style dark eye, small nose-less profile, same outline weight. Three separate heads in one horizontal row, evenly spaced with wide empty gaps between them, every head exactly the same size and the same angle, each in strict side profile facing RIGHT (nose side pointing to the right edge of the image). Each head ends in a short bare neck stub cut off straight at the bottom, no collar, no shirt, no tie, no body, no hands. LEFT head = tired normal face: heavy droopy half-closed eyelids, small flat tired mouth, only a very light faint thin pale-lavender line under the eye as a subtle eye bag (NOT a black eye, no dark circle, no bruise, no dark patch). MIDDLE head = panic: eye wide open and round with a tiny pupil, raised eyebrow, one blue sweat drop on the forehead, mouth wide open in a scream. RIGHT head = happy eating: eye closed in a blissful upward arc, pink blush on the cheek, cheek puffed out chewing with lips closed, no chopsticks, no food, no noodles, no hands, nothing sticking out beyond the head silhouette. No sparkles, no effects, no ground, no shadow, no text."),
 "leash": dict(ar="16:9", ref=[], p=PREFIX + " Obstacle sprite for the runner game, " + CHIBI + ". Wide horizontal composition: a plump cheerful middle-aged auntie walking her small dog on a long red leash. The auntie stands at the far LEFT end of the image, full body in strict side profile facing LEFT, short curly permed dark hair, coral floral-pattern blouse, lavender trousers, cream flat shoes. Her arm hangs down behind her and her hand holds a long thin bright red leash low at the height of her knees. The red leash runs straight and taut, almost perfectly horizontal, across most of the image width at the auntie's knee height, to the far RIGHT end of the image where a small fluffy cream-white dog (bichon-like) in strict side profile stands facing RIGHT, sniffing and pulling, the leash clipped to its teal collar. Big empty gap between the auntie and the dog, bridged only by the leash. Everything fully inside the frame with a small margin. No ground, no grass, no shadow, no motion lines, no text."),
 "scooter": dict(ar="1:1", ref=[], p=PREFIX + " Obstacle sprite for the runner game, " + CHIBI + ". A small happy kid (about six years old) riding a kick scooter, full body in strict side profile facing LEFT (face and scooter handlebar on the left side). The kid wears a round teal helmet, coral t-shirt, cream shorts, white sneakers, big open happy smile; both hands on the handlebar, one foot on the deck, the other foot kicking back. Kick scooter: tall lavender T-handlebar, lavender deck, two small round cream wheels with dark tires. Whole kid and scooter fully visible, single object centered with empty margin around. No ground, no shadow, no motion lines, no text."),
 "rider": dict(ar="4:3", ref=[], p=PREFIX + " Obstacle sprite for the runner game, " + CHIBI + ". A food-delivery rider seated on a small teal electric scooter-bike (step-through electric moped with a front shield and footboard, small wheels), whole vehicle in strict side profile facing RIGHT (headlight and handlebar on the right side). A big yellow square insulated delivery box is mounted on the rear rack behind the rider, completely plain yellow with no text, no logo, no symbols, no stripes. The rider wears a plain coral-red helmet with no markings, a cream windbreaker jacket, dark navy trousers, both hands on the handlebar, focused cheerful face. Dark tires with cream hubs. Whole rider and vehicle fully visible, single object centered with empty margin around. No ground, no shadow, no motion lines, no text, no license plate."),
 "bike": dict(ar="4:3", ref=[], p=PREFIX + " Obstacle prop for the runner game: a riderless shared city bicycle rolling by itself, strict side view, facing LEFT (front wheel, front basket and handlebar on the LEFT side, saddle and rear wheel on the right). Generic sturdy step-through city bike with a solid orange-red frame, cream front basket, dark saddle, chain guard, two round wheels with dark tires and cream solid hubs (no spokes needed). No rider. Completely plain frame: no logos, no text, no QR code, no numbers, no license plate, no decals. Whole bicycle fully visible, single object centered with empty margin around. No ground, no shadow, no motion lines, no text."),
}

def write(name, tag=None):
    j = JOBS[name]
    args = {"prompt": j["p"], "model": "gpt-image-2.5-flare", "quality": "medium", "aspectRatio": j["ar"], "imageSize": "2K", "background": "transparent", "name": tag or name}
    if j["ref"]:
        args["referenceImages"] = j["ref"]
    path = os.path.join(D, f"{tag or name}.json")
    json.dump({"command": "image.generate", "args": [args]}, open(path, "w", encoding="utf-8"))
    print(path)

if __name__ == "__main__":
    for n in sys.argv[1:]:
        write(n)
